79|static int array_list_expand_internal(struct array_list *arr, size_t max)
80|{
81|	void *t;
82|	size_t new_size;
83|
84|	if (max < arr->size)
85|		return 0;
86|	/* Avoid undefined behaviour on size_t overflow */
87|	if (arr->size >= SIZE_T_MAX / 2)
88|		new_size = max;
89|	else
90|	{
91|		new_size = arr->size << 1;
92|		if (new_size < max)
93|			new_size = max;
94|	}
95|	if (new_size > (~((size_t)0)) / sizeof(void *))
96|		return -1;
97|	if (!(t = realloc(arr->array, new_size * sizeof(void *))))
98|		return -1;
99|	arr->array = (void **)t;
100|	arr->size = new_size;
101|	return 0;
102|}

104|int array_list_shrink(struct array_list *arr, size_t empty_slots)
105|{
106|	void *t;
107|	size_t new_size;
108|
109|	new_size = arr->length + empty_slots;
110|	if (new_size == arr->size)
111|		return 0;
112|	if (new_size > arr->size)
113|		return array_list_expand_internal(arr, new_size);
114|	if (new_size == 0)
115|		new_size = 1;
116|
117|	if (!(t = realloc(arr->array, new_size * sizeof(void *))))
118|		return -1;
119|	arr->array = (void **)t;
120|	arr->size = new_size;
121|	return 0;
122|}

150|int array_list_add(struct array_list *arr, void *data)
151|{
152|	/* Repeat some of array_list_put_idx() so we can skip several
153|	   checks that we know are unnecessary when appending at the end
154|	 */
155|	size_t idx = arr->length;
156|	if (idx > SIZE_T_MAX - 1)
157|		return -1;
158|	if (array_list_expand_internal(arr, idx + 1))
159|		return -1;
160|	arr->array[idx] = data;
161|	arr->length++;
162|	return 0;
163|}

181|int array_list_del_idx(struct array_list *arr, size_t idx, size_t count)
182|{
183|	size_t i, stop;
184|
185|	/* Avoid overflow in calculation with large indices. */
186|	if (idx > SIZE_T_MAX - count)
187|		return -1;
188|	stop = idx + count;
189|	if (idx >= arr->length || stop > arr->length)
190|		return -1;
191|	for (i = idx; i < stop; ++i)
192|	{
193|		// Because put_idx can skip entries, we need to check if
194|		// there's actually anything in each slot we're erasing.
195|		if (arr->array[i])
196|			arr->free_fn(arr->array[i]);
197|	}
198|	memmove(arr->array + idx, arr->array + stop, (arr->length - stop) * sizeof(void *));
199|	arr->length -= count;
200|	return 0;
201|}

