1325|static int _json_object_set_string_len(json_object *jso, const char *s, size_t len)
1326|{
1327|	char *dstbuf;
1328|	ssize_t curlen;
1329|	ssize_t newlen;
1330|	if (jso == NULL || jso->o_type != json_type_string)
1331|		return 0;
1332|
1333|	if (len >= SSIZE_T_MAX - 1)
1334|		// jso->len is a signed ssize_t, so it can't hold the
1335|		// full size_t range.
1336|		return 0;
1337|
1338|	dstbuf = get_string_component_mutable(jso);
1339|	curlen = JC_STRING(jso)->len;
1340|	if (curlen < 0)
1341|		curlen = -curlen;
1342|	newlen = len;
1343|
1344|	if ((ssize_t)len > curlen)
1345|	{
1346|		// We have no way to return the new ptr from realloc(jso, newlen)
1347|		// and we have no way of knowing whether there's extra room available
1348|		// so we need to stuff a pointer in to pdata :(
1349|		dstbuf = (char *)malloc(len + 1);
1350|		if (dstbuf == NULL)
1351|			return 0;
1352|		if (JC_STRING(jso)->len < 0)
1353|			free(JC_STRING(jso)->c_string.pdata);
1354|		JC_STRING(jso)->c_string.pdata = dstbuf;
1355|		newlen = -(ssize_t)len;
1356|	}
1357|	else if (JC_STRING(jso)->len < 0)
1358|	{
1359|		// We've got enough room in the separate allocated buffer,
1360|		// so use it as-is and continue to indicate that pdata is used.
1361|		newlen = -(ssize_t)len;
1362|	}
1363|
1364|	memcpy(dstbuf, (const void *)s, len);
1365|	dstbuf[len] = '\0';
1366|	JC_STRING(jso)->len = newlen;
1367|	return 1;
