1701|static int json_object_deep_copy_recursive(struct json_object *src, struct json_object *parent,
1702|                                           const char *key_in_parent, size_t index_in_parent,
1703|                                           struct json_object **dst,
1704|                                           json_c_shallow_copy_fn *shallow_copy)
1705|{
1706|	struct json_object_iter iter;
1707|	size_t src_array_len, ii;
1708|
1709|	int shallow_copy_rc = 0;
1710|	shallow_copy_rc = shallow_copy(src, parent, key_in_parent, index_in_parent, dst);
1711|	/* -1=error, 1=object created ok, 2=userdata set */
1712|	if (shallow_copy_rc < 1)
1713|	{
1714|		errno = EINVAL;
1715|		return -1;
1716|	}
1717|	assert(*dst != NULL);
1718|
1719|	switch (src->o_type)
1720|	{
1721|	case json_type_object:
1722|		json_object_object_foreachC(src, iter)
1723|		{
1724|			struct json_object *jso = NULL;
1725|			/* This handles the `json_type_null` case */
1726|			if (!iter.val)
1727|				jso = NULL;
1728|			else if (json_object_deep_copy_recursive(iter.val, src, iter.key, -1, &jso,
1729|			                                         shallow_copy) < 0)
1730|			{
1731|				json_object_put(jso);
1732|				return -1;
1733|			}
1734|
1735|			if (json_object_object_add(*dst, iter.key, jso) < 0)
1736|			{
1737|				json_object_put(jso);
1738|				return -1;
1739|			}
1740|		}
1741|		break;
1742|
1743|	case json_type_array:
1744|		src_array_len = json_object_array_length(src);
1745|		for (ii = 0; ii < src_array_len; ii++)
1746|		{
1747|			struct json_object *jso = NULL;
1748|			struct json_object *jso1 = json_object_array_get_idx(src, ii);
1749|			/* This handles the `json_type_null` case */
1750|			if (!jso1)
1751|				jso = NULL;
1752|			else if (json_object_deep_copy_recursive(jso1, src, NULL, ii, &jso,
1753|			                                         shallow_copy) < 0)
1754|			{
1755|				json_object_put(jso);
1756|				return -1;
1757|			}
1758|
1759|			if (json_object_array_add(*dst, jso) < 0)
1760|			{
1761|				json_object_put(jso);
1762|				return -1;
1763|			}
1764|		}
1765|		break;
1766|
1767|	default:
1768|		break;
1769|		/* else, nothing to do, shallow_copy already did. */
1770|	}
1771|
1772|	if (shallow_copy_rc != 2)
1773|		return json_object_copy_serializer_data(src, *dst);
1774|
1775|	return 0;
1776|}

31|static int _json_c_visit(json_object *jso, json_object *parent_jso, const char *jso_key,
32|                         size_t *jso_index, json_c_visit_userfunc *userfunc, void *userarg)
33|{
34|	int userret = userfunc(jso, 0, parent_jso, jso_key, jso_index, userarg);
35|	switch (userret)
36|	{
37|	case JSON_C_VISIT_RETURN_CONTINUE: break;
38|	case JSON_C_VISIT_RETURN_SKIP:
39|	case JSON_C_VISIT_RETURN_POP:
40|	case JSON_C_VISIT_RETURN_STOP:
41|	case JSON_C_VISIT_RETURN_ERROR: return userret;
42|	default:
43|		fprintf(stderr, "ERROR: invalid return value from json_c_visit userfunc: %d\n",
44|		        userret);
45|		return JSON_C_VISIT_RETURN_ERROR;
46|	}
47|
48|	switch (json_object_get_type(jso))
49|	{
50|	case json_type_null:
51|	case json_type_boolean:
52|	case json_type_double:
53|	case json_type_int:
54|	case json_type_string:
55|		// we already called userfunc above, move on to the next object
56|		return JSON_C_VISIT_RETURN_CONTINUE;
57|
58|	case json_type_object:
59|	{
60|		json_object_object_foreach(jso, key, child)
61|		{
62|			userret = _json_c_visit(child, jso, key, NULL, userfunc, userarg);
63|			if (userret == JSON_C_VISIT_RETURN_POP)
64|				break;
65|			if (userret == JSON_C_VISIT_RETURN_STOP ||
66|			    userret == JSON_C_VISIT_RETURN_ERROR)
67|				return userret;
68|			if (userret != JSON_C_VISIT_RETURN_CONTINUE &&
69|			    userret != JSON_C_VISIT_RETURN_SKIP)
70|			{
71|				fprintf(stderr, "INTERNAL ERROR: _json_c_visit returned %d\n",
72|				        userret);
73|				return JSON_C_VISIT_RETURN_ERROR;
74|			}
75|		}
76|		break;
77|	}
78|	case json_type_array:
79|	{
80|		size_t array_len = json_object_array_length(jso);
81|		size_t ii;
82|		for (ii = 0; ii < array_len; ii++)
83|		{
84|			json_object *child = json_object_array_get_idx(jso, ii);
85|			userret = _json_c_visit(child, jso, NULL, &ii, userfunc, userarg);
86|			if (userret == JSON_C_VISIT_RETURN_POP)
87|				break;
88|			if (userret == JSON_C_VISIT_RETURN_STOP ||
89|			    userret == JSON_C_VISIT_RETURN_ERROR)
90|				return userret;
91|			if (userret != JSON_C_VISIT_RETURN_CONTINUE &&
92|			    userret != JSON_C_VISIT_RETURN_SKIP)
93|			{
94|				fprintf(stderr, "INTERNAL ERROR: _json_c_visit returned %d\n",
95|				        userret);
96|				return JSON_C_VISIT_RETURN_ERROR;
97|			}
98|		}
99|		break;
100|	}
101|	default:
102|		fprintf(stderr, "INTERNAL ERROR: _json_c_visit found object of unknown type: %d\n",
103|		        json_object_get_type(jso));
104|		return JSON_C_VISIT_RETURN_ERROR;
105|	}
106|
107|	// Call userfunc for the second type on container types, after all
108|	//  members of the container have been visited.
109|	// Non-container types will have already returned before this point.
110|
111|	userret = userfunc(jso, JSON_C_VISIT_SECOND, parent_jso, jso_key, jso_index, userarg);
112|	switch (userret)
113|	{
114|	case JSON_C_VISIT_RETURN_SKIP:
115|	case JSON_C_VISIT_RETURN_POP:
116|		// These are not really sensible during JSON_C_VISIT_SECOND,
117|		// but map them to JSON_C_VISIT_CONTINUE anyway.
118|		// FALLTHROUGH
119|	case JSON_C_VISIT_RETURN_CONTINUE: return JSON_C_VISIT_RETURN_CONTINUE;
120|	case JSON_C_VISIT_RETURN_STOP:
121|	case JSON_C_VISIT_RETURN_ERROR: return userret;
122|	default:
123|		fprintf(stderr, "ERROR: invalid return value from json_c_visit userfunc: %d\n",
124|		        userret);
125|		return JSON_C_VISIT_RETURN_ERROR;
126|	}
127|	// NOTREACHED
128|}

253|static uint32_t hashlittle(const void *key, size_t length, uint32_t initval)
254|{
255|	uint32_t a,b,c; /* internal state */
256|	union
257|	{
258|		const void *ptr;
259|		size_t i;
260|	} u; /* needed for Mac Powerbook G4 */
261|
262|	/* Set up the internal state */
263|	a = b = c = 0xdeadbeef + ((uint32_t)length) + initval;
264|
265|	u.ptr = key;
266|	if (HASH_LITTLE_ENDIAN && ((u.i & 0x3) == 0)) {
267|		const uint32_t *k = (const uint32_t *)key; /* read 32-bit chunks */
268|
269|		/*------ all but last block: aligned reads and affect 32 bits of (a,b,c) */
270|		while (length > 12)
271|		{
272|			a += k[0];
273|			b += k[1];
274|			c += k[2];
275|			mix(a,b,c);
276|			length -= 12;
277|			k += 3;
278|		}
279|
280|		/*----------------------------- handle the last (probably partial) block */
281|		/*
282|		 * "k[2]&0xffffff" actually reads beyond the end of the string, but
283|		 * then masks off the part it's not allowed to read.  Because the
284|		 * string is aligned, the masked-off tail is in the same word as the
285|		 * rest of the string.  Every machine with memory protection I've seen
286|		 * does it on word boundaries, so is OK with this.  But VALGRIND will
287|		 * still catch it and complain.  The masking trick does make the hash
288|		 * noticably faster for short strings (like English words).
289|		 * AddressSanitizer is similarly picky about overrunning
290|		 * the buffer. (http://clang.llvm.org/docs/AddressSanitizer.html
291|		 */
292|#ifdef VALGRIND
293|#define PRECISE_MEMORY_ACCESS 1
294|#elif defined(__SANITIZE_ADDRESS__) /* GCC's ASAN */
295|#define PRECISE_MEMORY_ACCESS 1
296|#elif defined(__has_feature)
297|#if __has_feature(address_sanitizer) /* Clang's ASAN */
298|#define PRECISE_MEMORY_ACCESS 1
299|#endif
300|#endif
301|#ifndef PRECISE_MEMORY_ACCESS
302|
303|		switch(length)
304|		{
305|		case 12: c+=k[2]; b+=k[1]; a+=k[0]; break;
306|		case 11: c+=k[2]&0xffffff; b+=k[1]; a+=k[0]; break;
307|		case 10: c+=k[2]&0xffff; b+=k[1]; a+=k[0]; break;
308|		case 9 : c+=k[2]&0xff; b+=k[1]; a+=k[0]; break;
309|		case 8 : b+=k[1]; a+=k[0]; break;
310|		case 7 : b+=k[1]&0xffffff; a+=k[0]; break;
311|		case 6 : b+=k[1]&0xffff; a+=k[0]; break;
312|		case 5 : b+=k[1]&0xff; a+=k[0]; break;
313|		case 4 : a+=k[0]; break;
314|		case 3 : a+=k[0]&0xffffff; break;
315|		case 2 : a+=k[0]&0xffff; break;
316|		case 1 : a+=k[0]&0xff; break;
317|		case 0 : return c; /* zero length strings require no mixing */
318|		}
319|
320|#else /* make valgrind happy */
321|
322|		const uint8_t  *k8 = (const uint8_t *)k;
323|		switch(length)
324|		{
