125|int array_list_put_idx(struct array_list *arr, size_t idx, void *data)
126|{
127|	if (idx > SIZE_T_MAX - 1)
128|		return -1;
129|	if (array_list_expand_internal(arr, idx + 1))
130|		return -1;
131|	if (idx < arr->length && arr->array[idx])
132|		arr->free_fn(arr->array[idx]);
133|	arr->array[idx] = data;
134|	if (idx > arr->length)
135|	{
136|		/* Zero out the arraylist slots in between the old length
137|		   and the newly added entry so we know those entries are
138|		   empty.
139|		   e.g. when setting array[7] in an array that used to be 
140|		   only 5 elements longs, array[5] and array[6] need to be
141|		   set to 0.
142|		 */
143|		memset(arr->array + arr->length, 0, (idx - arr->length) * sizeof(void *));
144|	}
145|	if (arr->length <= idx)
146|		arr->length = idx + 1;
147|	return 0;
148|}

