1570|int json_object_equal(struct json_object *jso1, struct json_object *jso2)
1571|{
1572|	if (jso1 == jso2)
1573|		return 1;
1574|
1575|	if (!jso1 || !jso2)
1576|		return 0;
1577|
1578|	if (jso1->o_type != jso2->o_type)
1579|		return 0;
1580|
1581|	switch (jso1->o_type)
1582|	{
1583|	case json_type_boolean: return (JC_BOOL(jso1)->c_boolean == JC_BOOL(jso2)->c_boolean);
1584|
1585|	case json_type_double: return (JC_DOUBLE(jso1)->c_double == JC_DOUBLE(jso2)->c_double);
1586|
1587|	case json_type_int:
1588|	{
1589|		struct json_object_int *int1 = JC_INT(jso1);
1590|		struct json_object_int *int2 = JC_INT(jso2);
1591|		if (int1->cint_type == json_object_int_type_int64)
1592|		{
1593|			if (int2->cint_type == json_object_int_type_int64)
1594|				return (int1->cint.c_int64 == int2->cint.c_int64);
1595|			if (int1->cint.c_int64 < 0)
1596|				return 0;
1597|			return ((uint64_t)int1->cint.c_int64 == int2->cint.c_uint64);
1598|		}
1599|		// else jso1 is a uint64
1600|		if (int2->cint_type == json_object_int_type_uint64)
1601|			return (int1->cint.c_uint64 == int2->cint.c_uint64);
1602|		if (int2->cint.c_int64 < 0)
1603|			return 0;
1604|		return (int1->cint.c_uint64 == (uint64_t)int2->cint.c_int64);
1605|	}
1606|
1607|	case json_type_string:
1608|	{
1609|		return (json_object_get_string_len(jso1) == json_object_get_string_len(jso2) &&
1610|		        memcmp(get_string_component(jso1), get_string_component(jso2),
1611|		               json_object_get_string_len(jso1)) == 0);
1612|	}
1613|
1614|	case json_type_object: return json_object_all_values_equal(jso1, jso2);
1615|
1616|	case json_type_array: return json_array_equal(jso1, jso2);
1617|
1618|	case json_type_null: return 1;
1619|	};
1620|
1621|	return 0;
1622|}

